140	impl ImeCursorRectangleSink for zwp_text_input_v3::ZwpTextInputV3 {
141	    fn set_ime_cursor_rectangle(&self, x: i32, y: i32, width: i32, height: i32) {
142	        self.set_cursor_rectangle(x, y, width, height);
