150	fn set_ime_cursor_rectangle(
151	    text_input: &impl ImeCursorRectangleSink,
152	    cursor_rectangle: ImeCursorRectangle,
153	) {
154	    text_input.set_ime_cursor_rectangle(
155	        cursor_rectangle.x,
156	        cursor_rectangle.y,
157	        cursor_rectangle.width,
158	        cursor_rectangle.height,
159	    );
160	}
161	
162	fn update_ime_cursor_rectangle(
163	    text_input: &impl ImeCursorRectangleSink,
164	    last_ime_cursor_rectangle: &mut Option<ImeCursorRectangle>,
165	    bounds: Bounds<Pixels>,
166	) {
167	    let cursor_rectangle = ImeCursorRectangle::from(bounds);
168	    if *last_ime_cursor_rectangle == Some(cursor_rectangle) {
169	        return;
170	    }
171	
172	    *last_ime_cursor_rectangle = Some(cursor_rectangle);
173	    set_ime_cursor_rectangle(text_input, cursor_rectangle);
174	    text_input.commit_ime_state();
175	}
176	
177	fn set_ime_cursor_rectangle_after_done(
178	    text_input: &impl ImeCursorRectangleSink,
179	    last_ime_cursor_rectangle: &mut Option<ImeCursorRectangle>,
180	    bounds: Bounds<Pixels>,
181	    should_commit: bool,
182	) {
183	    if should_commit {
184	        update_ime_cursor_rectangle(text_input, last_ime_cursor_rectangle, bounds);
185	    } else {
186	        set_ime_cursor_rectangle(text_input, ImeCursorRectangle::from(bounds));
187	    }
188	}
