190	fn take_startup_activation_token_from_environment() -> Option<String> {
191	    let startup_activation_token = std::env::var(XDG_ACTIVATION_TOKEN_ENV_VAR)
192	        .ok()
193	        .filter(|token| !token.is_empty());
194	    // The token must be removed from the environment so it isn't inherited by child
195	    // processes we spawn, per the xdg-activation spec: https://wayland.app/protocols/xdg-activation-v1
196	    // SAFETY: This runs during Wayland platform initialization before GPUI starts
197	    // concurrent environment access or spawning child processes.
198	    unsafe { std::env::remove_var(XDG_ACTIVATION_TOKEN_ENV_VAR) };
199	    startup_activation_token
200	}
