227	impl Globals {
228	    fn new(
229	        globals: GlobalList,
230	        executor: ForegroundExecutor,
231	        qh: QueueHandle<WaylandClientStatePtr>,
232	        seat: wl_seat::WlSeat,
233	    ) -> Self {
234	        let dialog_v = XdgWmDialogV1::interface().version;
235	        Globals {
236	            activation: globals.bind(&qh, 1..=1, ()).ok(),
