245	            cursor_shape_manager: globals.bind(&qh, 1..=1, ()).ok(),
246	            data_device_manager: globals
247	                .bind(
248	                    &qh,
249	                    WL_DATA_DEVICE_MANAGER_VERSION..=WL_DATA_DEVICE_MANAGER_VERSION,
250	                    (),
251	                )
252	                .ok(),
253	            primary_selection_manager: globals.bind(&qh, 1..=1, ()).ok(),
254	            shm: globals.bind(&qh, 1..=1, ()).unwrap(),
255	            seat,
256	            wm_base: globals.bind(&qh, 1..=5, ()).unwrap(),
257	            viewporter: globals.bind(&qh, 1..=1, ()).ok(),
258	            fractional_scale_manager: globals.bind(&qh, 1..=1, ()).ok(),
259	            decoration_manager: globals.bind(&qh, 1..=1, ()).ok(),
260	            layer_shell: globals.bind(&qh, 1..=5, ()).ok(),
261	            blur_manager: globals.bind(&qh, 1..=1, ()).ok(),
262	            text_input_manager: globals.bind(&qh, 1..=1, ()).ok(),
263	            gesture_manager: globals.bind(&qh, 1..=3, ()).ok(),
264	            dialog: globals.bind(&qh, dialog_v..=dialog_v, ()).ok(),
