381	fn file_uri_list(paths: &FileDragPaths) -> String {
382	    paths
383	        .entries()
384	        .iter()
385	        .filter_map(|(path, _)| Url::from_file_path(path).ok())
386	        .fold(String::new(), |mut list, url| {
